async function initEqVarChatKit(){
  const chatkit = document.getElementById('eqvar-chatkit');
  if(!chatkit || chatkit.dataset.initialized === 'true') return;

  const errorBox = document.getElementById('eqvar-chatkit-error');

  try {
    // The CDN registers <openai-chatkit> as a custom element.
    await customElements.whenDefined('openai-chatkit');

    chatkit.setOptions({
      api: {
        url: EQVAR_CHATKIT_API_URL,
        domainKey: EQVAR_CHATKIT_DOMAIN_KEY
      },
      theme: {
        colorScheme: 'light',
        density: 'compact',
        radius: 'round',
        color: {
          accent: {
            primary: '#51247A',
            level: 1
          }
        }
      },
      header: {
        title: { enabled: false }
      },
      startScreen: {
        greeting: 'Ask the ANOVA tutor about equal variance',
        prompts: [
          {
            label: 'How do I assess equal variance?',
            prompt: 'How should I use the boxplots and group standard deviations on this slide to assess the equal-variance assumption for one-way ANOVA?'
          },
          {
            label: 'What counts as similar SDs?',
            prompt: 'When checking the equal-variance assumption for one-way ANOVA, how similar should the group standard deviations be?'
          }
        ]
      },
      composer: {
        placeholder: 'Ask about the boxplots, SDs, or ANOVA assumption...'
      },
      threadItemActions: {
        feedback: false
      },
      onError: ({ error }) => {
        console.error('ChatKit error:', error);
        if(errorBox){
          errorBox.hidden = false;
          errorBox.textContent = 'ChatKit could not connect. Make sure the local backend is running at ' + EQVAR_CHATKIT_API_URL + '.';
        }
      },
      onReady: () => {
        if(errorBox) errorBox.hidden = true;
      }
    });

    chatkit.dataset.initialized = 'true';
  } catch (error) {
    console.error('Unable to initialize ChatKit:', error);
    if(errorBox){
      errorBox.hidden = false;
      errorBox.textContent = 'Unable to initialize ChatKit. Check the browser console and confirm the ChatKit CDN is reachable.';
    }
  }
}

